function slatesPath(slateId: number, suffix: string): string {
  return `/api/v1/dfs/slates/${encodeURIComponent(String(slateId))}${suffix}`;
}

function normalizePollPath(
  location: string | null,
  status: SimJobStatusResponse | null,
  slateId: number,
): string {
  const raw =
    location ||
    status?.poll_url ||
    (status?.job_id ? slatesPath(slateId, `/sim/jobs/${encodeURIComponent(status.job_id)}`) : '');
  if (!raw)
    throw new StatApiError(
      202,
      status,
      slatesPath(slateId, '/sim/lineups'),
      'stat-api: 202 response missing Location and poll_url',
    );
  if (raw.startsWith('http://') || raw.startsWith('https://')) {
    const u = new URL(raw);
    return `${u.pathname}${u.search}`;
  }
  return raw;
}

function parseJsonOrThrow<T>(text: string, path: string): T {
  try {
    return JSON.parse(text) as T;
  } catch (err) {
    throw new StatApiError(500, text, path, `stat-api: invalid JSON response: ${String(err)}`);
  }
}

function sleepMs(ms: number): Promise<void> {
  return ms <= 0 ? Promise.resolve() : new Promise((resolve) => setTimeout(resolve, ms));
}

async function pollUntilReady<T>(
  opts: ResolvedStatApiOptions,
  slateId: number,
  initialPath: string,
  initial: Awaited<ReturnType<typeof fetchRaw>>,
  simOpts: SimRequestOptions | undefined,
  expectCsv: boolean,
): Promise<T> {
  if (initial.status !== 202) {
    return expectCsv
      ? (initial.text as unknown as T)
      : parseJsonOrThrow<T>(initial.text, initialPath);
  }
  const timeoutMs = simOpts?.timeoutMs ?? 120_000;
  const deadline = Date.now() + timeoutMs;
  let current = initial;
  let pollPath = normalizePollPath(
    current.headers.get('Location'),
    parseJsonOrThrow<SimJobStatusResponse>(current.text, initialPath),
    slateId,
  );

  for (;;) {
    const statusBody = parseJsonOrThrow<SimJobStatusResponse>(current.text, pollPath);
    if (statusBody.status === 'failed') {
      throw new StatApiError(500, statusBody, pollPath, statusBody.error ?? 'SIM job failed');
    }
    const retryHeader = current.headers.get('Retry-After');
    const retrySec =
      retryHeader !== null && retryHeader !== ''
        ? Number(retryHeader)
        : statusBody.retry_after_seconds;
    const defaultDelay = Number.isFinite(retrySec) ? Math.max(0, retrySec * 1000) : 1000;
    const delayMs = simOpts?.pollIntervalMs !== undefined ? simOpts.pollIntervalMs : defaultDelay;
    const remaining = deadline - Date.now();
    if (remaining <= 0) {
      throw new NotReadyError(statusBody, pollPath, retryHeader);
    }
    await sleepMs(Math.min(delayMs, remaining));
    current = await fetchRaw(opts, pollPath, {
      method: 'GET',
      headers: expectCsv ? { Accept: 'text/csv, application/json;q=0.9' } : undefined,
    });
    if (current.status !== 202) {
      return expectCsv
        ? (current.text as unknown as T)
        : parseJsonOrThrow<T>(current.text, pollPath);
    }
    pollPath = normalizePollPath(
      current.headers.get('Location'),
      parseJsonOrThrow<SimJobStatusResponse>(current.text, pollPath),
      slateId,
    );
  }
}

export async function optimizerLineups(
  opts: ResolvedStatApiOptions,
  slateId: number,
  request: OptimizerLineupsRequest = {},
): Promise<OptimizerLineupsResponse> {
  const path = slatesPath(slateId, '/optimizer/lineups');
  const res = await fetchRaw(opts, path, {
    method: 'POST',
    body: JSON.stringify({ ...request, response_format: 'json' }),
  });
  return parseJsonOrThrow<OptimizerLineupsResponse>(res.text, path);
}

export async function optimizerLineupsCsv(
  opts: ResolvedStatApiOptions,
  slateId: number,
  request: OptimizerLineupsRequest = {},
): Promise<string> {
  const path = slatesPath(slateId, '/optimizer/lineups');
  const res = await fetchRaw(opts, path, {
    method: 'POST',
    headers: { Accept: 'text/csv, application/json;q=0.9' },
    body: JSON.stringify({ ...request, response_format: 'csv' }),
  });
  return res.text;
}

